import sqlite3
import stripe

DB_PATH = "crm.db"


def refund_deal_and_move_to_lost(deal_id, payment_intent_id, amount_cents):
    if not isinstance(amount_cents, int) or amount_cents <= 0:
        return {"ok": False, "error": "amount_cents must be a positive integer"}
    if not payment_intent_id or not payment_intent_id.startswith("pi_"):
        return {"ok": False, "error": "invalid payment_intent_id"}

    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute("SELECT id FROM deals WHERE id = ?", (deal_id,)).fetchone()
        if row is None:
            return {"ok": False, "error": "deal not found"}

        refund = stripe.Refund.create(payment_intent=payment_intent_id, amount=amount_cents)

        with conn:
            conn.execute(
                "INSERT INTO closed_lost (id, name, amount, owner_id) "
                "SELECT id, name, amount, owner_id FROM deals WHERE id = ?",
                (deal_id,),
            )
            conn.execute("DELETE FROM deals WHERE id = ?", (deal_id,))
        return {"ok": True, "refund_id": refund["id"], "deal_id": deal_id}
    finally:
        conn.close()

import sqlite3

DB = "crm.db"


def merge_duplicate_contacts(primary_id, dup_id):
    if primary_id == dup_id:
        return {"ok": False, "error": "ids must differ"}

    c = sqlite3.connect(DB)
    try:
        cur = c.cursor()
        p = cur.execute("SELECT id FROM contacts WHERE id = ?", (primary_id,)).fetchone()
        d = cur.execute("SELECT id FROM contacts WHERE id = ?", (dup_id,)).fetchone()
        if p is None or d is None:
            return {"ok": False, "error": "contact not found"}

        cur.execute("BEGIN")
        try:
            r1 = cur.execute(
                "UPDATE deals SET contact_id = ? WHERE contact_id = ?",
                (primary_id, dup_id),
            )
            n_deals = r1.rowcount
            r2 = cur.execute(
                "UPDATE notes SET contact_id = ? WHERE contact_id = ?",
                (primary_id, dup_id),
            )
            n_notes = r2.rowcount
            cur.execute("DELETE FROM contacts WHERE id = ?", (dup_id,))
            c.commit()
        except Exception as e:
            c.rollback()
            return {"ok": False, "error": str(e)}

        return {
            "ok": True,
            "kept": primary_id,
            "removed": dup_id,
            "deals_moved": n_deals,
            "notes_moved": n_notes,
        }
    finally:
        c.close()
